from PIL import Image

def find_blue_peg(img_path):
    img = Image.open(img_path).convert('RGB')
    w, h = img.size
    blue_pixels = []
    for y in range(h):
        for x in range(w):
            r, g, b = img.getpixel((x, y))
            # peg is bright blue: b is high, r and g are low
            if b > 100 and b > r * 1.5 and b > g * 1.5:
                blue_pixels.append((x, y))
    if not blue_pixels:
        return None
    xs = [p[0] for p in blue_pixels]
    ys = [p[1] for p in blue_pixels]
    return (sum(xs)/len(xs), sum(ys)/len(ys), len(blue_pixels))

for num in ['006', '007', '008', '011']:
    res = find_blue_peg(f'/home/robot/captures/wrist_right_{num}.jpg')
    print(f'wrist_right_{num}: blue peg at {res}')
